export const STATIC: Record<string, { type: string; body: string }> = {"/app.js":{"type":"text/javascript; charset=utf-8","body":"(() => {\n  const $ = (id) => document.getElementById(id);\n  const state = { config: null, type: null, from: null, slots: {}, date: null, start: null };\n  const visitorTz = Intl.DateTimeFormat().resolvedOptions().timeZone || \"Europe/London\";\n\n  const steps = [\"type\", \"time\", \"form\", \"done\"];\n  function show(step) {\n    for (const s of steps) $(\"step-\" + s).hidden = s !== step;\n    window.scrollTo({ top: 0 });\n  }\n\n  function el(tag, attrs = {}, ...children) {\n    const e = document.createElement(tag);\n    for (const [k, v] of Object.entries(attrs)) {\n      if (k === \"class\") e.className = v;\n      else if (k.startsWith(\"on\")) e.addEventListener(k.slice(2), v);\n      else e.setAttribute(k, v);\n    }\n    for (const c of children) e.append(c);\n    return e;\n  }\n\n  const fmt = (opts, tz = visitorTz) => new Intl.DateTimeFormat(\"en-GB\", { timeZone: tz, ...opts });\n  const timeFmt = fmt({ hour: \"2-digit\", minute: \"2-digit\", hourCycle: \"h23\" });\n  const longFmt = fmt({ weekday: \"long\", day: \"numeric\", month: \"long\", hour: \"2-digit\", minute: \"2-digit\", hourCycle: \"h23\", timeZoneName: \"short\" });\n\n  function addDays(d, n) {\n    const t = new Date(d + \"T00:00:00Z\");\n    t.setUTCDate(t.getUTCDate() + n);\n    return t.toISOString().slice(0, 10);\n  }\n\n  async function api(path, opts) {\n    const res = await fetch(path, opts);\n    const body = await res.json().catch(() => ({}));\n    if (!res.ok) throw new Error(body.error || \"Something went wrong. Please try again.\");\n    return body;\n  }\n\n  async function init() {\n    state.config = await api(\"/api/config\");\n    const list = $(\"types\");\n    for (const t of state.config.eventTypes) {\n      list.append(\n        el(\"button\", { class: \"card\", type: \"button\", role: \"listitem\", onclick: () => chooseType(t) },\n          el(\"span\", { class: \"name\" }, t.name),\n          el(\"span\", { class: \"meta\" }, `${t.durationMin} minutes`),\n          el(\"span\", {}, t.description)),\n      );\n    }\n    const pre = new URLSearchParams(location.search).get(\"type\");\n    const match = state.config.eventTypes.find((t) => t.slug === pre);\n    if (match) chooseType(match);\n  }\n\n  async function chooseType(t) {\n    state.type = t;\n    state.from = null;\n    $(\"time-eyebrow\").textContent = t.name;\n    $(\"form-eyebrow\").textContent = t.name;\n    const tzLabel = visitorTz === state.config.timezone ? \"UK time\" : `your time zone (${visitorTz})`;\n    $(\"tz-note\").textContent = `${t.durationMin} minutes. Times are shown in ${tzLabel}.`;\n    show(\"time\");\n    await loadWeek();\n  }\n\n  async function loadWeek() {\n    $(\"days\").replaceChildren();\n    $(\"times\").replaceChildren(el(\"p\", { class: \"empty\" }, \"Loading times…\"));\n    const q = new URLSearchParams({ type: state.type.slug, days: \"14\" });\n    if (state.from) q.set(\"from\", state.from);\n    try {\n      const data = await api(\"/api/slots?\" + q);\n      state.from = data.from;\n      state.last = data.lastBookableDate;\n      state.slots = data.slots;\n      renderDays(data);\n    } catch (e) {\n      $(\"times\").replaceChildren(el(\"p\", { class: \"empty\" }, e.message));\n    }\n  }\n\n  function renderDays(data) {\n    const days = $(\"days\");\n    days.replaceChildren();\n    let first = null;\n    for (let i = 0; i < data.days; i++) {\n      const d = addDays(data.from, i);\n      const has = (state.slots[d] || []).length > 0;\n      const dt = new Date(d + \"T12:00:00Z\");\n      const b = el(\"button\", { class: \"day\", type: \"button\", role: \"tab\", \"aria-selected\": \"false\", onclick: () => chooseDate(d) },\n        fmt({ weekday: \"short\" }, \"UTC\").format(dt), el(\"b\", {}, String(dt.getUTCDate())), fmt({ month: \"short\" }, \"UTC\").format(dt));\n      if (!has) b.disabled = true;\n      b.dataset.date = d;\n      days.append(b);\n      if (has && !first) first = d;\n    }\n    $(\"prev-week\").disabled = !state.from || state.from <= new Date().toISOString().slice(0, 10);\n    $(\"next-week\").disabled = addDays(data.from, data.days) > state.last;\n    if (first) chooseDate(first);\n    else $(\"times\").replaceChildren(el(\"p\", { class: \"empty\" }, \"No times in these two weeks. Try later dates.\"));\n  }\n\n  function chooseDate(d) {\n    state.date = d;\n    for (const b of $(\"days\").children) b.setAttribute(\"aria-selected\", String(b.dataset.date === d));\n    const times = $(\"times\");\n    times.replaceChildren();\n    for (const iso of state.slots[d] || []) {\n      times.append(el(\"button\", { class: \"time\", type: \"button\", role: \"listitem\", onclick: () => chooseTime(iso) }, timeFmt.format(new Date(iso))));\n    }\n  }\n\n  function chooseTime(iso) {\n    state.start = iso;\n    $(\"chosen\").textContent = longFmt.format(new Date(iso));\n    const qs = $(\"questions\");\n    qs.replaceChildren();\n    for (const q of state.type.questions) {\n      let input;\n      if (q.type === \"select\") {\n        input = el(\"select\", { name: \"q_\" + q.id }, el(\"option\", { value: \"\" }, \"Choose…\"));\n        for (const o of q.options) input.append(el(\"option\", { value: o }, o));\n      } else if (q.type === \"textarea\") input = el(\"textarea\", { name: \"q_\" + q.id, maxlength: \"2000\" });\n      else input = el(\"input\", { name: \"q_\" + q.id, maxlength: \"2000\" });\n      if (q.required) input.required = true;\n      qs.append(el(\"label\", {}, q.label + (q.required ? \"\" : \" (optional)\"), input));\n    }\n    $(\"form-error\").textContent = \"\";\n    show(\"form\");\n  }\n\n  $(\"form\").addEventListener(\"submit\", async (ev) => {\n    ev.preventDefault();\n    const f = new FormData(ev.target);\n    const answers = {};\n    for (const q of state.type.questions) answers[q.id] = (f.get(\"q_\" + q.id) || \"\").toString();\n    const btn = $(\"submit\");\n    btn.disabled = true;\n    $(\"form-error\").textContent = \"\";\n    try {\n      const res = await api(\"/api/bookings\", {\n        method: \"POST\",\n        headers: { \"content-type\": \"application/json\" },\n        body: JSON.stringify({ type: state.type.slug, start: state.start, name: f.get(\"name\"), email: f.get(\"email\"), website: f.get(\"website\"), answers }),\n      });\n      $(\"done-when\").textContent = `${state.type.name}, ${longFmt.format(new Date(res.start))}`;\n      $(\"ics-link\").href = `/api/bookings/${encodeURIComponent(res.manageToken)}.ics`;\n      show(\"done\");\n    } catch (e) {\n      $(\"form-error\").textContent = e.message;\n      if (/no longer available|just been taken/.test(e.message)) setTimeout(() => { show(\"time\"); loadWeek(); }, 1800);\n    } finally {\n      btn.disabled = false;\n    }\n  });\n\n  $(\"prev-week\").addEventListener(\"click\", () => { state.from = addDays(state.from, -14); loadWeek(); });\n  $(\"next-week\").addEventListener(\"click\", () => { state.from = addDays(state.from, 14); loadWeek(); });\n  for (const b of document.querySelectorAll(\"[data-back]\")) b.addEventListener(\"click\", () => show(b.dataset.back));\n\n  init().catch((e) => { $(\"types\").replaceChildren(el(\"p\", { class: \"empty\" }, e.message)); });\n})();\n"},"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en-GB\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Book a call · Alderlux</title>\n<meta name=\"description\" content=\"Book a private call with Alderlux: Bitcoin Intelligence and Wealth Preservation.\">\n<link rel=\"preconnect\" href=\"https://api.fontshare.com\">\n<link rel=\"stylesheet\" href=\"https://api.fontshare.com/v2/css?f[]=satoshi@400,500,700&display=swap\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<header class=\"band\">\n  <div class=\"wrap\"><a class=\"wordmark\" href=\"https://alderlux.com\">ALDERLUX</a></div>\n</header>\n<main class=\"wrap\" id=\"app\" aria-live=\"polite\">\n  <section id=\"step-type\">\n    <p class=\"eyebrow\">Book a call</p>\n    <h1>Choose a conversation</h1>\n    <div id=\"types\" class=\"cards\" role=\"list\"></div>\n  </section>\n\n  <section id=\"step-time\" hidden>\n    <button class=\"back\" data-back=\"type\" type=\"button\">&larr; Back</button>\n    <p class=\"eyebrow\" id=\"time-eyebrow\"></p>\n    <h1>Choose a time</h1>\n    <p class=\"muted\" id=\"tz-note\"></p>\n    <div class=\"days\" id=\"days\" role=\"tablist\" aria-label=\"Days\"></div>\n    <div class=\"times\" id=\"times\" role=\"list\"></div>\n    <div class=\"pager\"><button type=\"button\" id=\"prev-week\" class=\"link\">Earlier</button><button type=\"button\" id=\"next-week\" class=\"link\">Later</button></div>\n  </section>\n\n  <section id=\"step-form\" hidden>\n    <button class=\"back\" data-back=\"time\" type=\"button\">&larr; Back</button>\n    <p class=\"eyebrow\" id=\"form-eyebrow\"></p>\n    <h1>Your details</h1>\n    <p class=\"chosen\" id=\"chosen\"></p>\n    <form id=\"form\" novalidate>\n      <label>Name<input name=\"name\" autocomplete=\"name\" required maxlength=\"120\"></label>\n      <label>Email<input name=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"254\"></label>\n      <div id=\"questions\"></div>\n      <label class=\"hp\" aria-hidden=\"true\">Website<input name=\"website\" tabindex=\"-1\" autocomplete=\"off\"></label>\n      <p class=\"fine\">We use your details only to arrange and hold this call. We never ask for seed phrases, private keys or passwords.</p>\n      <p class=\"error\" id=\"form-error\" role=\"alert\"></p>\n      <button class=\"primary\" type=\"submit\" id=\"submit\">Confirm booking</button>\n    </form>\n  </section>\n\n  <section id=\"step-done\" hidden>\n    <p class=\"eyebrow\">Confirmed</p>\n    <h1>Your call is booked</h1>\n    <p class=\"chosen\" id=\"done-when\"></p>\n    <p>A confirmation is on its way by email, with a link to change or cancel.</p>\n    <p><a class=\"primary\" id=\"ics-link\" href=\"#\">Add to calendar</a></p>\n  </section>\n</main>\n<footer class=\"wrap foot\">\n  <hr>\n  <p class=\"fine\" id=\"footer\">Alderlux provides education and information only. We do not provide regulated financial advice, investment recommendations, legal or tax advice. Alderlux is not authorised by the Financial Conduct Authority.</p>\n</footer>\n<script src=\"/app.js\" defer></script>\n</body>\n</html>\n"},"/manage.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en-GB\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex\">\n<title>Your booking · Alderlux</title>\n<link rel=\"stylesheet\" href=\"https://api.fontshare.com/v2/css?f[]=satoshi@400,500,700&display=swap\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<header class=\"band\"><div class=\"wrap\"><a class=\"wordmark\" href=\"https://alderlux.com\">ALDERLUX</a></div></header>\n<main class=\"wrap\" aria-live=\"polite\">\n  <p class=\"eyebrow\">Your booking</p>\n  <h1 id=\"title\">Loading…</h1>\n  <p class=\"chosen\" id=\"when\" hidden></p>\n  <p id=\"where\" class=\"muted\"></p>\n  <p id=\"actions\" hidden>\n    <a class=\"primary\" id=\"ics\" href=\"#\">Add to calendar</a>\n  </p>\n  <p id=\"cancel-wrap\" hidden><button class=\"link\" id=\"cancel\" type=\"button\">Cancel this call</button></p>\n  <p><a class=\"link\" href=\"/\">Book another time</a></p>\n  <p class=\"error\" id=\"error\" role=\"alert\"></p>\n</main>\n<footer class=\"wrap foot\"><hr><p class=\"fine\">Alderlux provides education and information only. We do not provide regulated financial advice, investment recommendations, legal or tax advice. Alderlux is not authorised by the Financial Conduct Authority.</p></footer>\n<script src=\"/manage.js\" defer></script>\n</body>\n</html>\n"},"/manage.js":{"type":"text/javascript; charset=utf-8","body":"(() => {\n  const $ = (id) => document.getElementById(id);\n  const t = new URLSearchParams(location.search).get(\"t\") || \"\";\n  const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || \"Europe/London\";\n  const longFmt = new Intl.DateTimeFormat(\"en-GB\", { timeZone: tz, weekday: \"long\", day: \"numeric\", month: \"long\", year: \"numeric\", hour: \"2-digit\", minute: \"2-digit\", hourCycle: \"h23\", timeZoneName: \"short\" });\n\n  async function load() {\n    const res = await fetch(`/api/bookings/${encodeURIComponent(t)}`);\n    const b = await res.json().catch(() => ({}));\n    if (!res.ok) { $(\"title\").textContent = \"Booking not found\"; return; }\n    $(\"title\").textContent = b.status === \"cancelled\" ? \"This call is cancelled\" : b.name;\n    $(\"when\").hidden = false;\n    $(\"when\").textContent = longFmt.format(new Date(b.start));\n    $(\"where\").textContent = b.location;\n    const upcoming = b.status === \"confirmed\" && Date.parse(b.start) > Date.now();\n    $(\"actions\").hidden = !upcoming;\n    $(\"cancel-wrap\").hidden = !upcoming;\n    $(\"ics\").href = `/api/bookings/${encodeURIComponent(t)}.ics`;\n  }\n\n  $(\"cancel\").addEventListener(\"click\", async () => {\n    if (!confirm(\"Cancel this call?\")) return;\n    $(\"cancel\").disabled = true;\n    const res = await fetch(`/api/bookings/${encodeURIComponent(t)}/cancel`, { method: \"POST\" });\n    const b = await res.json().catch(() => ({}));\n    if (!res.ok) { $(\"error\").textContent = b.error || \"Could not cancel. Please try again.\"; $(\"cancel\").disabled = false; return; }\n    load();\n  });\n\n  load().catch(() => { $(\"title\").textContent = \"Something went wrong\"; });\n})();\n"},"/style.css":{"type":"text/css; charset=utf-8","body":":root {\n  --alx-ground: #0B0B0D;\n  --alx-surface: #141416;\n  --alx-hairline: #2A2926;\n  --alx-ink: #F7F4EE;\n  --alx-body: #D8D1C3;\n  --alx-muted: #A9A196;\n  --alx-gold: #C9A86A;\n  --alx-error: #F2B8A8;\n}\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  background: var(--alx-ground, #0B0B0D);\n  color: var(--alx-body, #D8D1C3);\n  font-family: Satoshi, system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  font-size: 16px;\n  line-height: 1.6;\n  -webkit-font-smoothing: antialiased;\n}\n.wrap { max-width: 720px; margin: 0 auto; padding: 0 16px; }\n.band { border-top: 3px solid var(--alx-gold); border-bottom: 1px solid var(--alx-hairline); }\n.band .wrap { padding-top: 20px; padding-bottom: 20px; }\n.wordmark { color: var(--alx-gold); text-decoration: none; letter-spacing: 0.32em; font-weight: 500; font-size: 15px; }\nmain { padding-top: 32px; padding-bottom: 24px; }\nh1 { color: var(--alx-ink); font-weight: 400; font-size: clamp(26px, 5vw, 34px); line-height: 1.2; margin: 4px 0 20px; }\n.eyebrow { color: var(--alx-gold); font-size: 11px; font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; margin: 0; }\n.muted { color: var(--alx-muted); font-size: 14px; }\n.fine { color: var(--alx-muted); font-size: 13px; line-height: 1.5; }\n.cards { display: grid; gap: 12px; }\n.card {\n  display: block; width: 100%; text-align: left; cursor: pointer;\n  background: var(--alx-surface); color: var(--alx-body); border: 1px solid var(--alx-hairline);\n  padding: 18px 20px; font: inherit; border-radius: 2px;\n}\n.card:hover, .card:focus-visible { border-color: var(--alx-gold); outline: none; }\n.card .name { color: var(--alx-ink); font-size: 18px; font-weight: 500; display: block; }\n.card .meta { color: var(--alx-gold); font-size: 13px; letter-spacing: 0.06em; display: block; margin: 2px 0 6px; }\n.days { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 8px; margin: 16px 0; scrollbar-width: thin; }\n.day {\n  flex: 0 0 auto; min-width: 72px; background: var(--alx-surface); border: 1px solid var(--alx-hairline);\n  color: var(--alx-body); padding: 10px 8px; font: inherit; font-size: 13px; text-align: center; cursor: pointer; border-radius: 2px;\n}\n.day b { display: block; color: var(--alx-ink); font-size: 18px; font-weight: 500; }\n.day[aria-selected=\"true\"] { border-color: var(--alx-gold); }\n.day:disabled { opacity: 0.35; cursor: default; }\n.times { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 8px; min-height: 48px; }\n.time {\n  background: transparent; border: 1px solid var(--alx-gold); color: var(--alx-ink); padding: 12px 0; font: inherit; cursor: pointer; border-radius: 2px;\n}\n.time:hover, .time:focus-visible { background: var(--alx-gold); color: var(--alx-ground); outline: none; }\n.pager { display: flex; justify-content: space-between; margin-top: 16px; }\n.link { background: none; border: 0; color: var(--alx-gold); font: inherit; cursor: pointer; padding: 8px 0; }\n.link:disabled { opacity: 0.35; cursor: default; }\n.back { background: none; border: 0; color: var(--alx-muted); font: inherit; cursor: pointer; padding: 0 0 12px; }\n.chosen { color: var(--alx-ink); border-left: 3px solid var(--alx-gold); padding-left: 12px; }\nform label { display: block; margin: 0 0 16px; color: var(--alx-ink); font-size: 14px; }\ninput, select, textarea {\n  display: block; width: 100%; margin-top: 6px; padding: 12px; font: inherit; font-size: 16px;\n  background: var(--alx-surface); color: var(--alx-ink); border: 1px solid var(--alx-hairline); border-radius: 2px;\n}\ninput:focus, select:focus, textarea:focus { outline: none; border-color: var(--alx-gold); }\ntextarea { min-height: 96px; resize: vertical; }\n.hp { position: absolute; left: -10000px; width: 1px; height: 1px; overflow: hidden; }\n.primary {\n  display: inline-block; background: var(--alx-gold); color: var(--alx-ground); border: 0; padding: 16px 32px;\n  font: inherit; font-size: 12px; font-weight: 700; letter-spacing: 0.18em; text-transform: uppercase; cursor: pointer; text-decoration: none; border-radius: 2px;\n}\n.primary:disabled { opacity: 0.6; cursor: progress; }\n.error { color: var(--alx-error); min-height: 1.4em; }\n.empty { color: var(--alx-muted); grid-column: 1 / -1; }\n.foot hr { border: 0; border-top: 1px solid var(--alx-hairline); }\n.foot { padding-bottom: 32px; }\n@media (prefers-reduced-motion: no-preference) { .card, .time, .day { transition: border-color .15s, background .15s; } }\n"}};
